UPDATE public.pages SET builder_data = jsonb_set(builder_data, '{sections}', (builder_data->'sections') || '{"id": "a74e1958-c367-45cc-9e3b-9343981e3ac3", "kind": "section", "layout": {"width": 1200, "contentWidth": "boxed"}, "children": [{"id": "caa1b3b8-d127-4160-abf2-ff06a16bfe0c", "kind": "column", "span": {"desktop": 4}, "children": [{"id": "1f742f25-a43a-4d55-8554-38fd5b6d929c", "kind": "widget", "type": "icon", "content": {"name": "Users", "size": 48, "color": "#f97316", "align": "center"}}, {"id": "42085fb4-e978-438c-be9e-f002bdc97952", "kind": "widget", "type": "heading", "content": {"tag": "h3", "text_pl": "Konferencja", "text_en": "Conference", "align": "center", "sizePreset": "lg"}}, {"id": "617dbb67-3d40-4035-b33e-545c59f546c0", "kind": "widget", "type": "text", "content": {"html_pl": "<p style=\"text-align:center\">Konferencja „Geopolityczna Gra Mocarstw\" umożliwia wypracowanie wspólnych strategii dla Europy. Integruje ekspertów i decydentów w ramach dialogu interdyscyplinarnego. Wzmacnia pozycję Polski w europejskiej polityce i gospodarce.</p>", "html_en": "<p style=\"text-align:center\">The „Geopolitical Game of Powers\" conference enables the development of common strategies for Europe. It brings together experts and decision-makers in interdisciplinary dialogue. It strengthens Poland''s position in European politics and economy.</p>"}}]}, {"id": "82085785-6bdb-4737-9682-8a106b2e154f", "kind": "column", "span": {"desktop": 4}, "children": [{"id": "96549bb6-7adb-4e14-bbe5-83adee33eaee", "kind": "widget", "type": "icon", "content": {"name": "FileText", "size": 48, "color": "#f97316", "align": "center"}}, {"id": "a4298012-0f28-4fb5-8b63-16a608a2558d", "kind": "widget", "type": "heading", "content": {"tag": "h3", "text_pl": "Raporty i Policy Papers", "text_en": "Reports and Policy Papers", "align": "center", "sizePreset": "lg"}}, {"id": "9712fbfe-e861-4345-ae24-63f5df87061c", "kind": "widget", "type": "text", "content": {"html_pl": "<p style=\"text-align:center\">Dostarczają pogłębionej wiedzy o aktualnych tematach poprzez cykliczne rozmowy z ekspertami i decydentami. Oferują unikalne analizy i perspektywy, wzbogacając debatę publiczną oraz ułatwiając zrozumienie złożonych procesów globalnych i regionalnych.</p>", "html_en": "<p style=\"text-align:center\">They deliver in-depth knowledge on current topics through regular conversations with experts and decision-makers. They offer unique analyses and perspectives, enriching public debate and facilitating understanding of complex global and regional processes.</p>"}}]}, {"id": "b78489e9-4322-4390-bb58-c7f22aed07df", "kind": "column", "span": {"desktop": 4}, "children": [{"id": "88b33bdb-bfd7-4282-aecb-f25f990841b3", "kind": "widget", "type": "icon", "content": {"name": "Handshake", "size": 48, "color": "#f97316", "align": "center"}}, {"id": "5d9aa70d-83dc-44e0-90b8-b431ba8937ce", "kind": "widget", "type": "heading", "content": {"tag": "h3", "text_pl": "Spotkania", "text_en": "Meetings", "align": "center", "sizePreset": "lg"}}, {"id": "fc6806b5-cac5-4a53-b56e-d80872ddee76", "kind": "widget", "type": "text", "content": {"html_pl": "<p style=\"text-align:center\">Spotkania w formule „Chatham House\" zapewniają poufną i otwartą debatę nad trudnymi tematami. Integrują i wspierają rozwój projektów biznesowo-politycznych, w tym trwałych relacji międzysektorowych.</p>", "html_en": "<p style=\"text-align:center\">„Chatham House\" format meetings ensure confidential and open debate on difficult topics. They integrate and support the development of business-political projects, including lasting cross-sectoral relationships.</p>"}}]}]}'::jsonb) WHERE id = '2d7776f2-d1ad-437e-8607-62b39c2b37a2';